class Game {
  + isHiddenTileFound : boolean
}

class Board {
  + layout : string
}

class Tile {
  + isHidden : boolean
  + isActionTile : boolean
  + color : string
  + actionTileDuration : int
}

class Connection {
  + side : string
}

class ActionCard {
  + type : ActionType
}

class Player {
  + color : string
  + currentPosition : Tile
}

class PlayingPiece {
  + color : string
}

class Die {
  + value : int
}

